 async Task Run(){Check(File.Exists(Path.Combine(Root,"PROBE-ONLY")),"Refusing non-test profile");var step=JObject.Parse(File.ReadAllText(Path.Combine(Root,"save-scenario.json")));var plugin=(PlaytimePlugin)PlayniteApi.Addons.Plugins.Single(p=>p.Id==new Guid("8ca18482-3ebe-4bf7-b229-a259b2094767"));var repo=(Repository)Field(plugin,"repository");var key=repo.Snapshot().Mappings.Single().Value.Key;var game=PlayniteApi.Database.Games.Get(new Guid(repo.Snapshot().Mappings.Single().Key));var vault=(Vault)Field(plugin,"vault");var dir=vault.State.Links[key].Folder;Check(Path.GetFullPath(dir).StartsWith(Path.GetFullPath(Root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase),"Not a fixture folder");
 if((bool?)step["Interactive"]==false){((OnboardingOptions)Field(plugin,"onboarding")).SyncPaused=false;((DevicePreferences)Field(plugin,"devicePreferences")).AutoSync=true;}var start=DateTime.UtcNow;while(plugin.IsSyncRunning){Check((DateTime.UtcNow-start).TotalSeconds<60,"Startup did not settle");await Task.Delay(100);}if(step["Write"]!=null)Write(dir,(string)step["Write"]);
 var beforeHash=Revision.ContentHashOf(SaveFiles.Capture(dir));var beforeSaveHash=Revision.ContentHashOf(((BlobStore)Field(plugin,"blobs")).Capture(dir));var backupsBefore=Directory.GetDirectories(Path.GetDirectoryName(dir),Path.GetFileName(dir)+".pl-backup-*");var checkpoint=JsonConvert.SerializeObject(vault.State.Links[key].Save);var choice=(string)step["Choice"];bool stopRequested=false;int dialogs=0;Exception uiError=null;var watcher=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};
