 bool failed=false,stoppedTransfer=false;var cfg=(SyncConfig)Field(plugin,"config");var original=cfg.ConfigFile;if((bool?)step["CancelTransfer"]==true)((DevicePreferences)Field(plugin,"devicePreferences")).BandwidthKiB=128;watcher.Start();try{if((bool?)step["Fail"]==true)cfg.ConfigFile=Path.Combine(Root,"missing-rclone.conf");if((bool?)step["ViaGamePage"]==true){bool clicked=false;var pageTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};var pageStart=DateTime.UtcNow;pageTimer.Tick+=(_,e)=>{var page=Application.Current.Windows.OfType<Window>().FirstOrDefault(w=>w.IsVisible&&w.Title=="Playnite Link — "+game.Name);if(page==null)return;try{if(!clicked){var action=Controls<Button>(page).Single(b=>Convert.ToString(b.Content)=="Choose saves…");Check(action.IsVisible&&action.IsEnabled,"No direct conflict action on game page");Capture(page,"conflict-game-action");clicked=true;action.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}else if(((SyncProgress)Field(plugin,"syncProgress")).Read().Title=="Up to date"&&!plugin.IsSyncRunning)page.Close();Check((DateTime.UtcNow-pageStart).TotalSeconds<180,"Game-page resolution did not finish");}catch(Exception ex){uiError=ex;page.Close();}};pageTimer.Start();try{typeof(PlaytimePlugin).GetMethod("Manage",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(plugin,new object[]{game});}finally{pageTimer.Stop();}Check(clicked,"Game page was not used");}
 else if((bool?)step["Sync"]!=false)await plugin.SyncPersonalAsync((bool?)step["Interactive"]!=false,null);}catch(OperationCanceledException){if((bool?)step["CancelTransfer"]!=true)throw;stoppedTransfer=true;}catch(Exception){if((bool?)step["Fail"]!=true)throw;failed=true;}finally{watcher.Stop();cfg.ConfigFile=original;}if(uiError!=null)throw uiError;
 if(stoppedTransfer)Check(plugin.IsSyncPaused,"Stopped upload resumed automatically");Check(stoppedTransfer==((bool?)step["CancelTransfer"]==true),"Transfer cancellation mismatch");Check(failed==((bool?)step["Fail"]==true),"Failure test mismatch");if((bool?)step["AllowConflict"]!=true)Check((dialogs>0)==((bool?)step["Conflict"]==true),"Conflict prompt expectation mismatch");Verify(dir,(string)step["Expect"]);if(choice=="cancel"||choice=="close"||failed)Check(checkpoint==JsonConvert.SerializeObject(vault.State.Links[key].Save)||vault.State.Links[key].Save.Content==beforeSaveHash,"Cancel/failure accepted a different save version");
 var backupsAfter=Directory.GetDirectories(Path.GetDirectoryName(dir),Path.GetFileName(dir)+".pl-backup-*");var changed=beforeHash!=Revision.ContentHashOf(SaveFiles.Capture(dir));if(changed){var created=backupsAfter.Except(backupsBefore).ToArray();Check(created.Length==1,"Restore did not preserve one backup");Check(Revision.ContentHashOf(SaveFiles.Capture(created[0]))==beforeHash,"Backup bytes differ from replaced local saves");}if(choice=="cancel"||choice=="close"||failed)Check(backupsAfter.Length==backupsBefore.Length,"Cancel/failure replaced local saves");
 Check(game.Playtime==16&&game.PlayCount==2,"Save sync changed playtime or session count");Check(repo.Snapshot().Mappings.Count==1,"Duplicate game mapping");var backup=typeof(PlaytimePlugin).GetField("LastBackup",BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public);var beforeBackups=Directory.GetDirectories(Path.GetDirectoryName(dir),Path.GetFileName(dir)+".pl-backup-*").Length;
 Finish(new{passed=true,name=(string)step["Name"],choice,dialogs,expected=(string)step["Expect"],playtime=game.Playtime,sessions=game.PlayCount,filesVerified=true,stoppedTransfer,backupBytesVerified=changed,checkpointPreserved=choice=="cancel"||choice=="close"||failed,backupFolders=beforeBackups});
